<?php
require_once 'includes/config.php'; require_admin();
$qtext=trim($_GET['q']??'');$action=trim($_GET['action']??'');$from=trim($_GET['from']??'');$to=trim($_GET['to']??'');$where=['1=1'];$p=[];
if($qtext){$where[]='(username LIKE :q OR details LIKE :q OR ip_address LIKE :q)';$p[':q']='%'.$qtext.'%';}if($action){$where[]='action=:a';$p[':a']=$action;}if($from){$where[]='created_at>=:f';$p[':f']=$from.' 00:00:00';}if($to){$where[]='created_at<=:t';$p[':t']=$to.' 23:59:59';}
$actions=$dbh->query('SELECT DISTINCT action FROM admin_activity_logs ORDER BY action')->fetchAll(PDO::FETCH_COLUMN);$sql='SELECT * FROM admin_activity_logs WHERE '.implode(' AND ',$where).' ORDER BY id DESC LIMIT 500';$st=$dbh->prepare($sql);$st->execute($p);$rows=$st->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Audit Logs | SRMS</title><link rel="stylesheet" href="css/bootstrap.min.css"><link rel="stylesheet" href="css/font-awesome.min.css"><link rel="stylesheet" href="css/main.css"><link rel="stylesheet" href="css/srms-modernization.css"><link rel="stylesheet" href="css/srms-responsive.css"></head><body class="top-navbar-fixed"><div class="main-wrapper"><?php include 'includes/topbar.php';?><div class="content-wrapper"><div class="content-container"><?php include 'includes/leftbar.php';?><div class="main-page"><div class="container-fluid"><div class="row page-title-div"><div class="col-sm-8"><h2 class="title">Audit Logs</h2><p class="text-muted">Administrative and teacher actions recorded by SRMS. Showing up to 500 matching entries.</p></div></div><form class="panel panel-default panel-body" method="get"><div class="row"><div class="col-md-3"><label>Search</label><input class="form-control" name="q" value="<?php echo e($qtext);?>" placeholder="User, details or IP"></div><div class="col-md-3"><label>Action</label><select class="form-control" name="action"><option value="">All actions</option><?php foreach($actions as $a):?><option value="<?php echo e($a);?>" <?php echo $action===$a?'selected':'';?>><?php echo e($a);?></option><?php endforeach;?></select></div><div class="col-md-2"><label>From</label><input class="form-control" type="date" name="from" value="<?php echo e($from);?>"></div><div class="col-md-2"><label>To</label><input class="form-control" type="date" name="to" value="<?php echo e($to);?>"></div><div class="col-md-2"><label>&nbsp;</label><button class="btn btn-primary btn-block">Filter</button></div></div></form><div class="panel"><div class="panel-body"><div class="table-responsive"><table class="table table-bordered table-striped table-condensed"><thead><tr><th>Date/Time</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?php echo e($r['created_at']);?></td><td><?php echo e($r['username']);?></td><td><span class="label label-info"><?php echo e($r['action']);?></span></td><td><?php echo e($r['details']);?></td><td><?php echo e($r['ip_address']);?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="5" class="text-center">No audit entries found.</td></tr><?php endif;?></tbody></table></div></div></div></div></div></div></div></div><script src="js/jquery/jquery-2.2.4.min.js"></script><script src="js/bootstrap/bootstrap.min.js"></script></body></html>
